INSERT INTO public.businesses(id,owner_id,name,business_type,slug) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','00000000-0000-4000-a074-000000000001','Voice','general','voice-074');
INSERT INTO public.voice_pilot_settings(business_id,enabled) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26',true);
INSERT INTO public.subscriptions(business_id,stripe_customer_id,stripe_subscription_id,plan,status) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','cus_voice','sub_voice','sms_and_chat','active');
INSERT INTO public.contacts(id,business_id,phone_number,source_channel) VALUES ('20000000-0000-4000-a074-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','+15555550101','voice');
INSERT INTO public.conversations(id,business_id,contact_id,channel) VALUES ('30000000-0000-4000-a074-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','20000000-0000-4000-a074-000000000001','voice');
INSERT INTO public.voice_sessions(id,business_id,conversation_id,call_control_id,call_session_id,caller_phone,called_phone,response_mode,status,reserved_seconds) VALUES ('40000000-0000-4000-a074-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','30000000-0000-4000-a074-000000000001','control','session','+15555550101','+15742638634','voice','active',600);

INSERT INTO public.voice_pilot_testers(business_id,phone_number) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','+15555550101');
SELECT is((public.claim_voice_preparation('40000000-0000-4000-a074-000000000001')).id,NULL::uuid,'active call cannot be prepared again');
UPDATE public.voice_sessions SET status='ringing';
UPDATE public.voice_pilot_settings SET preparation_enabled=true;
SELECT is((public.claim_voice_preparation('40000000-0000-4000-a074-000000000001')).id,NULL::uuid,'no preparation without prior tester acknowledgment');
UPDATE public.voice_pilot_testers SET prior_disclosure_acknowledged_at=now()-interval '1 day';
SELECT is((public.claim_voice_preparation('40000000-0000-4000-a074-000000000001')).id,'40000000-0000-4000-a074-000000000001'::uuid,'eligible ringing call prepared once');
SELECT is((public.claim_voice_preparation('40000000-0000-4000-a074-000000000001')).id,NULL::uuid,'duplicate preparation cannot open a second model');
SELECT public.finalize_voice_session('40000000-0000-4000-a074-000000000001','caller_abandoned',NULL,true,true);
SELECT is((SELECT usage_confirmed FROM public.voice_sessions LIMIT 1),false,'prepared call cannot be declared free');
UPDATE public.voice_sessions SET created_at=now()-interval '10 minutes';
SELECT public.reconcile_unstarted_voice_sessions();
SELECT is((SELECT usage_confirmed FROM public.voice_sessions LIMIT 1),false,'unstarted reconciliation preserves unknown preparation charges');
SELECT ok(NOT has_function_privilege('authenticated','public.claim_voice_preparation(uuid)','EXECUTE'),'preparation cannot be called by a user');
SELECT ok(NOT has_function_privilege('authenticated','public.configure_voice_actions(integer,boolean,boolean,boolean,boolean,uuid,text,jsonb,uuid)','EXECUTE'),'capabilities cannot be granted by a user');
SELECT * FROM finish();
ROLLBACK;
